def smallestSufficientTeam(req_skills: list[str], people: list[list[str]]) -> list[int]:
    skill_map = {s: i for i, s in enumerate(req_skills)}
    target = (1 << len(req_skills)) - 1
    dp = {0: []}
    for person_idx, skills in enumerate(people):
        p_mask = 0
        for s in skills:
            if s in skill_map: p_mask |= (1 << skill_map[s])
        if p_mask == 0: continue
        curr_items = list(dp.items())
        for mask, team in curr_items:
            comb = mask | p_mask
            if comb not in dp or len(team) + 1 < len(dp[comb]):
                dp[comb] = team + [person_idx]
    return sorted(dp[target])

